	CONSTRAINT fk_integration_message_updated_by_user_id_app_user FOREIGN KEY(updated_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT ck_integration_message_direction_codes CHECK (direction IN ('outbound', 'inbound')), 
	CONSTRAINT ck_integration_message_status_codes CHECK (status IN ('queued', 'sending', 'sent', 'acknowledged', 'received', 'processed', 'failed', 'dead-letter')), 
	CONSTRAINT uq_integration_message_tenant_id_id UNIQUE (tenant_id, id)
);

