	entity_type VARCHAR(64), 
	entity_id VARCHAR(64), 
	entity_version_id INTEGER, 
	patient_id UUID, 
	purpose_of_use VARCHAR(20), 
	reason VARCHAR(500), 
	source_ip INET, 
	user_agent VARCHAR(300), 
