	CONSTRAINT ck_family_member_history_fhir_deceased_age_comparator CHECK (deceased_age_comparator IS NULL OR deceased_age_value IS NOT NULL), 
	CONSTRAINT ck_family_member_history_fhir_born_x CHECK (((born_period_start IS NOT NULL OR born_period_end IS NOT NULL))::int + ((born_date IS NOT NULL))::int + ((born_string IS NOT NULL))::int <= 1), 
	CONSTRAINT ck_family_member_history_fhir_age_x CHECK (((age_age_value IS NOT NULL OR age_age_code IS NOT NULL))::int + ((age_range_low_value IS NOT NULL OR age_range_high_value IS NOT NULL))::int + ((age_string IS NOT NULL))::int <= 1), 
	CONSTRAINT ck_family_member_history_fhir_deceased_x CHECK (((deceased_boolean IS NOT NULL))::int + ((deceased_age_value IS NOT NULL OR deceased_age_code IS NOT NULL))::int + ((deceased_date IS NOT NULL))::int + ((deceased_string IS NOT NULL))::int <= 1), 
