CREATE TABLE clinical.contact_point (
	patient_id UUID, 
	practitioner_id UUID, 
	practitioner_role_id UUID, 
	organization_id UUID, 
	location_id UUID, 
	related_person_id UUID, 
	patient_contact_id UUID, 
	system VARCHAR(40) NOT NULL, 
	value VARCHAR(254) NOT NULL, 
	use VARCHAR(40), 
	rank INTEGER, 
	period_start TIMESTAMP WITH TIME ZONE, 
	period_end TIMESTAMP WITH TIME ZONE, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_contact_point PRIMARY KEY (id), 
	CONSTRAINT ck_contact_point_rank_positive CHECK (rank IS NULL OR rank >= 1), 
	CONSTRAINT ck_contact_point_email_format CHECK (system <> 'email' OR value ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'), 
	CONSTRAINT ck_contact_point_phone_format CHECK (system NOT IN ('phone', 'fax', 'sms') OR value ~ '^\+?[0-9 ().-]{7,25}$'), 
	CONSTRAINT fk_contact_point_patient_id_patient FOREIGN KEY(patient_id) REFERENCES clinical.patient (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_practitioner_id_practitioner FOREIGN KEY(practitioner_id) REFERENCES clinical.practitioner (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_practitioner_role_id_practitioner_role FOREIGN KEY(practitioner_role_id) REFERENCES clinical.practitioner_role (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_organization_id_organization FOREIGN KEY(organization_id) REFERENCES clinical.organization (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_location_id_location FOREIGN KEY(location_id) REFERENCES clinical.location (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_related_person_id_related_person FOREIGN KEY(related_person_id) REFERENCES clinical.related_person (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_patient_contact_id_patient_contact FOREIGN KEY(patient_contact_id) REFERENCES clinical.patient_contact (id) ON DELETE CASCADE, 
	CONSTRAINT fk_contact_point_tenant_id_tenant FOREIGN KEY(tenant_id) REFERENCES admin.tenant (id) ON DELETE RESTRICT, 
	CONSTRAINT ck_contact_point_system_codes CHECK (system IN ('phone', 'fax', 'email', 'pager', 'url', 'sms', 'other')), 
	CONSTRAINT ck_contact_point_use_codes CHECK (use IN ('home', 'work', 'temp', 'old', 'mobile')), 
	CONSTRAINT ck_contact_point_fhir_period_per_1 CHECK (period_end IS NULL OR period_start IS NULL OR period_start <= period_end), 
	CONSTRAINT ck_contact_point_one_owner CHECK (num_nonnulls(patient_id, practitioner_id, practitioner_role_id, organization_id, location_id, related_person_id, patient_contact_id) = 1)
);

CREATE INDEX ix_contact_point_location_id ON clinical.contact_point (location_id);

CREATE INDEX ix_contact_point_organization_id ON clinical.contact_point (organization_id);

CREATE INDEX ix_contact_point_patient_contact_id ON clinical.contact_point (patient_contact_id);

CREATE INDEX ix_contact_point_patient_id ON clinical.contact_point (patient_id);

CREATE INDEX ix_contact_point_phone ON clinical.contact_point (tenant_id, regexp_replace(value, '[^0-9]', '', 'g')) WHERE system IN ('phone', 'sms');

