CREATE TABLE clinical.address (
	patient_id UUID, 
	practitioner_id UUID, 
	organization_id UUID, 
	location_id UUID, 
	related_person_id UUID, 
	patient_contact_id UUID, 
	use VARCHAR(40), 
	type VARCHAR(40), 
	text VARCHAR(500), 
	line VARCHAR(200)[] DEFAULT '{}' NOT NULL, 
	city VARCHAR(100), 
	district VARCHAR(100), 
	state VARCHAR(50), 
	postal_code VARCHAR(20), 
	country VARCHAR(2), 
	period_start TIMESTAMP WITH TIME ZONE, 
	period_end TIMESTAMP WITH TIME ZONE, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_address PRIMARY KEY (id), 
	CONSTRAINT ck_address_us_state CHECK (country IS DISTINCT FROM 'US' OR state IS NULL OR state ~ '^[A-Z]{2}$'), 
	CONSTRAINT ck_address_us_zip CHECK (country IS DISTINCT FROM 'US' OR postal_code IS NULL OR postal_code ~ '^[0-9]{5}(-[0-9]{4})?$'), 
	CONSTRAINT ck_address_has_content CHECK (cardinality(line) > 0 OR city IS NOT NULL OR postal_code IS NOT NULL OR text IS NOT NULL), 
	CONSTRAINT fk_address_patient_id_patient FOREIGN KEY(patient_id) REFERENCES clinical.patient (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_practitioner_id_practitioner FOREIGN KEY(practitioner_id) REFERENCES clinical.practitioner (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_organization_id_organization FOREIGN KEY(organization_id) REFERENCES clinical.organization (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_location_id_location FOREIGN KEY(location_id) REFERENCES clinical.location (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_related_person_id_related_person FOREIGN KEY(related_person_id) REFERENCES clinical.related_person (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_patient_contact_id_patient_contact FOREIGN KEY(patient_contact_id) REFERENCES clinical.patient_contact (id) ON DELETE CASCADE, 
	CONSTRAINT fk_address_tenant_id_tenant FOREIGN KEY(tenant_id) REFERENCES admin.tenant (id) ON DELETE RESTRICT, 
	CONSTRAINT ck_address_use_codes CHECK (use IN ('home', 'work', 'temp', 'old', 'billing')), 
	CONSTRAINT ck_address_type_codes CHECK ("type" IN ('postal', 'physical', 'both')), 
	CONSTRAINT ck_address_fhir_period_per_1 CHECK (period_end IS NULL OR period_start IS NULL OR period_start <= period_end), 
	CONSTRAINT ck_address_one_owner CHECK (num_nonnulls(patient_id, practitioner_id, organization_id, location_id, related_person_id, patient_contact_id) = 1)
);

