	ai_suggestion_id UUID, 
	CONSTRAINT pk_coverage PRIMARY KEY (id), 
	CONSTRAINT ck_coverage_order_range CHECK ("order" IS NULL OR "order" BETWEEN 1 AND 9), 
	CONSTRAINT ck_coverage_self_has_no_related_subscriber CHECK (relationship_code <> 'self' OR subscriber_related_person_id IS NULL), 
	CONSTRAINT ck_coverage_period_order CHECK (period_end IS NULL OR period_start IS NULL OR period_end >= period_start), 
	CONSTRAINT ck_coverage_meta_security_codes CHECK (meta_security <@ ARRAY['L', 'M', 'N', 'R', 'V', 'PSY', 'SUD', 'ETH', 'HIV', 'SEX', 'SOC', 'CEL']::varchar[]), 
	CONSTRAINT ck_coverage_extension_is_array CHECK (jsonb_typeof(extension) = 'array'), 
	CONSTRAINT fk_coverage_type_system_code_system FOREIGN KEY(type_system) REFERENCES admin.code_system (uri) ON UPDATE CASCADE, 
	CONSTRAINT fk_coverage_policy_holder_patient_id_patient FOREIGN KEY(policy_holder_patient_id) REFERENCES clinical.patient (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_coverage_policy_holder_related_person_id_related_person FOREIGN KEY(policy_holder_related_person_id) REFERENCES clinical.related_person (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_coverage_subscriber_patient_id_patient FOREIGN KEY(subscriber_patient_id) REFERENCES clinical.patient (id) ON DELETE RESTRICT, 
