	CONSTRAINT fk_coverage_beneficiary_patient_id_patient FOREIGN KEY(beneficiary_patient_id) REFERENCES clinical.patient (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_coverage_tenant_id_tenant FOREIGN KEY(tenant_id) REFERENCES admin.tenant (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_coverage_created_by_user_id_app_user FOREIGN KEY(created_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT fk_coverage_updated_by_user_id_app_user FOREIGN KEY(updated_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT fk_coverage_verified_by_user_id_app_user FOREIGN KEY(verified_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT ck_coverage_status_codes CHECK (status IN ('active', 'cancelled', 'draft', 'entered-in-error')), 
	CONSTRAINT ck_coverage_relationship_code_codes CHECK (relationship_code IN ('child', 'parent', 'spouse', 'common', 'other', 'self', 'injured')), 
	CONSTRAINT ck_coverage_entry_source_codes CHECK (entry_source IN ('clinician', 'imported', 'patient-reported', 'ai-generated', 'device', 'interface')), 
	CONSTRAINT ck_coverage_fhir_type_coding CHECK ((type_code IS NULL) = (type_system IS NULL)), 
	CONSTRAINT ck_coverage_fhir_type_display CHECK (type_display IS NULL OR type_code IS NOT NULL), 
	CONSTRAINT ck_coverage_fhir_policy_holder_arc CHECK (num_nonnulls(policy_holder_patient_id, policy_holder_related_person_id) <= 1), 
	CONSTRAINT ck_coverage_fhir_subscriber_arc CHECK (num_nonnulls(subscriber_patient_id, subscriber_related_person_id) <= 1), 
	CONSTRAINT ck_coverage_fhir_period_per_1 CHECK (period_end IS NULL OR period_start IS NULL OR period_start <= period_end), 
	CONSTRAINT uq_coverage_tenant_id_id UNIQUE (tenant_id, id), 
	CONSTRAINT uq_coverage_beneficiary_patient_id_id UNIQUE (beneficiary_patient_id, id), 
	CONSTRAINT ck_coverage_ai_entry_verified CHECK (entry_source <> 'ai-generated' OR (ai_suggestion_id IS NOT NULL AND verified_by_user_id IS NOT NULL))
);

