	service_type_text VARCHAR(1000), 
	appointment_type_system VARCHAR(300), 
	appointment_type_code VARCHAR(64), 
	appointment_type_display VARCHAR(500), 
	appointment_type_text VARCHAR(1000), 
	priority INTEGER, 
	description VARCHAR(500), 
	start TIMESTAMP WITH TIME ZONE, 
	"end" TIMESTAMP WITH TIME ZONE, 
	minutes_duration INTEGER, 
	created TIMESTAMP WITH TIME ZONE, 
	comment VARCHAR(2000), 
	patient_instruction VARCHAR(2000), 
	subject_patient_id UUID NOT NULL, 
	ext_appointment_type_id UUID, 
	ext_schedule_id UUID, 
	ext_facility_id UUID, 
	ext_same_day_add_on BOOLEAN DEFAULT false NOT NULL, 
	ext_overbook BOOLEAN DEFAULT false NOT NULL, 
	ext_rescheduled_from_appointment_id UUID, 
	ext_cancelled_at TIMESTAMP WITH TIME ZONE, 
	ext_cancelled_by_user_id UUID, 
	meta_version_id INTEGER DEFAULT 1 NOT NULL, 
	meta_last_updated TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	meta_txid BIGINT, 
	meta_security VARCHAR(10)[] DEFAULT '{}' NOT NULL, 
	extension JSONB DEFAULT '[]' NOT NULL, 
	id UUID NOT NULL, 
	tenant_id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	created_by_user_id UUID, 
	updated_by_user_id UUID, 
	CONSTRAINT pk_appointment PRIMARY KEY (id), 
	CONSTRAINT ck_appointment_fhir_app_2 CHECK ((start IS NULL) = ("end" IS NULL)), 
	CONSTRAINT ck_appointment_fhir_app_3 CHECK (start IS NOT NULL OR status IN ('proposed', 'cancelled', 'waitlist')), 
	CONSTRAINT ck_appointment_fhir_app_4 CHECK (cancelation_reason_code IS NULL AND cancelation_reason_text IS NULL OR status IN ('cancelled', 'noshow')), 
	CONSTRAINT ck_appointment_end_after_start CHECK ("end" IS NULL OR "end" > start), 
	CONSTRAINT ck_appointment_duration_positive CHECK (minutes_duration IS NULL OR minutes_duration > 0), 
	CONSTRAINT ck_appointment_cancelled_has_time CHECK (status <> 'cancelled' OR ext_cancelled_at IS NOT NULL), 
	CONSTRAINT ck_appointment_not_rescheduled_from_self CHECK (ext_rescheduled_from_appointment_id IS DISTINCT FROM id), 
	CONSTRAINT ck_appointment_meta_security_codes CHECK (meta_security <@ ARRAY['L', 'M', 'N', 'R', 'V', 'PSY', 'SUD', 'ETH', 'HIV', 'SEX', 'SOC', 'CEL']::varchar[]), 
	CONSTRAINT ck_appointment_extension_is_array CHECK (jsonb_typeof(extension) = 'array'), 
	CONSTRAINT fk_appointment_cancelation_reason_system_code_system FOREIGN KEY(cancelation_reason_system) REFERENCES admin.code_system (uri) ON UPDATE CASCADE, 
	CONSTRAINT fk_appointment_service_category_system_code_system FOREIGN KEY(service_category_system) REFERENCES admin.code_system (uri) ON UPDATE CASCADE, 
	CONSTRAINT fk_appointment_service_type_system_code_system FOREIGN KEY(service_type_system) REFERENCES admin.code_system (uri) ON UPDATE CASCADE, 
	CONSTRAINT fk_appointment_appointment_type_system_code_system FOREIGN KEY(appointment_type_system) REFERENCES admin.code_system (uri) ON UPDATE CASCADE, 
	CONSTRAINT fk_appointment_subject_patient_id_patient FOREIGN KEY(subject_patient_id) REFERENCES clinical.patient (id), 
	CONSTRAINT fk_appointment_ext_appointment_type_id_appointment_type FOREIGN KEY(ext_appointment_type_id) REFERENCES admin.appointment_type (id), 
	CONSTRAINT fk_appointment_ext_schedule_id_schedule FOREIGN KEY(ext_schedule_id) REFERENCES clinical.schedule (id), 
	CONSTRAINT fk_appointment_ext_facility_id_facility FOREIGN KEY(ext_facility_id) REFERENCES admin.facility (id), 
	CONSTRAINT fk_appointment_ext_rescheduled_from_appointment_id_appointment FOREIGN KEY(ext_rescheduled_from_appointment_id) REFERENCES clinical.appointment (id), 
	CONSTRAINT fk_appointment_ext_cancelled_by_user_id_app_user FOREIGN KEY(ext_cancelled_by_user_id) REFERENCES admin.app_user (id), 
	CONSTRAINT fk_appointment_tenant_id_tenant FOREIGN KEY(tenant_id) REFERENCES admin.tenant (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_appointment_created_by_user_id_app_user FOREIGN KEY(created_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT fk_appointment_updated_by_user_id_app_user FOREIGN KEY(updated_by_user_id) REFERENCES admin.app_user (id) ON DELETE SET NULL, 
	CONSTRAINT ck_appointment_status_codes CHECK (status IN ('proposed', 'pending', 'booked', 'arrived', 'fulfilled', 'cancelled', 'noshow', 'entered-in-error', 'checked-in', 'waitlist')), 
	CONSTRAINT ck_appointment_fhir_cancelation_reason_coding CHECK ((cancelation_reason_code IS NULL) = (cancelation_reason_system IS NULL)), 
	CONSTRAINT ck_appointment_fhir_cancelation_reason_display CHECK (cancelation_reason_display IS NULL OR cancelation_reason_code IS NOT NULL), 
	CONSTRAINT ck_appointment_fhir_service_category_coding CHECK ((service_category_code IS NULL) = (service_category_system IS NULL)), 
	CONSTRAINT ck_appointment_fhir_service_category_display CHECK (service_category_display IS NULL OR service_category_code IS NOT NULL), 
	CONSTRAINT ck_appointment_fhir_service_type_coding CHECK ((service_type_code IS NULL) = (service_type_system IS NULL)), 
	CONSTRAINT ck_appointment_fhir_service_type_display CHECK (service_type_display IS NULL OR service_type_code IS NOT NULL), 
	CONSTRAINT ck_appointment_fhir_appointment_type_coding CHECK ((appointment_type_code IS NULL) = (appointment_type_system IS NULL)), 
	CONSTRAINT ck_appointment_fhir_appointment_type_display CHECK (appointment_type_display IS NULL OR appointment_type_code IS NOT NULL), 
	CONSTRAINT uq_appointment_tenant_id_id UNIQUE (tenant_id, id), 
	CONSTRAINT uq_appointment_subject_patient_id_id UNIQUE (subject_patient_id, id)
);

