	CONSTRAINT ck_diagnostic_report_status_codes CHECK (status IN ('registered', 'partial', 'preliminary', 'final', 'amended', 'corrected', 'appended', 'cancelled', 'entered-in-error', 'unknown')), 
	CONSTRAINT ck_diagnostic_report_entry_source_codes CHECK (entry_source IN ('clinician', 'imported', 'patient-reported', 'ai-generated', 'device', 'interface')), 
	CONSTRAINT ck_diagnostic_report_fhir_code_coding CHECK ((code_code IS NULL) = (code_system IS NULL)), 
